window.VOCAB_HAUSAUFGABEN = [{"id":"01-konjunktiv","no":1,"title":"Konjunktiv","title_en":"Konjunktiv II e frasi con wenn · weil, wegen, deswegen, denn","added":"2026-11-06","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 4","pages":[{"page":"AB 130","heading":"A  Wenn ich du wäre, würde ich …","heading_en":"Se fossi in te, …","exercises":[{"no":"1","tag":"Wiederholung A2, L8","instruction":"Evas Realität – Evas Wünsche. Ergänzen Sie: *würde – hätte – wäre*.","instruction_en":"La realtà di Eva – i desideri di Eva. Completa con: würde – hätte – wäre.","box":["würde","hätte","wäre"],"example":[{"label":"a","lead":"Eva hat rote Haare.","text":"Sie **hätte** aber gern schwarze Haare."}],"items":[{"label":"b","lead":"Sie ist ein bisschen klein.","text":"Sie ___ aber gern grösser.","gaps":[["wäre"]],"solution":"Sie **wäre** aber gern grösser.","en":"Però le piacerebbe essere più alta.","why":"*grösser sein*: la forma del desiderio di *sein* è **wäre**.","source":"k2"},{"label":"c","lead":"Sie kann nicht Spanisch sprechen.","text":"Sie ___ aber gern gut Spanisch sprechen.","gaps":[["würde"]],"solution":"Sie **würde** aber gern gut Spanisch sprechen.","en":"Però le piacerebbe parlare bene lo spagnolo.","why":"Alla fine c'è un infinito (*sprechen*), quindi il desiderio è **würde** + infinito.","source":"k2"},{"label":"d","lead":"Sie arbeitet in einem Reisebüro.","text":"Sie ___ aber lieber als Reiseführerin arbeiten.","gaps":[["würde"]],"solution":"Sie **würde** aber lieber als Reiseführerin arbeiten.","en":"Però preferirebbe lavorare come guida turistica.","why":"Infinito alla fine (*arbeiten*) → **würde** + infinito. *lieber* = piuttosto, preferibilmente.","source":"k2"},{"label":"e","lead":"Sie hat eine sehr kleine Wohnung.","text":"Sie ___ aber gern eine grosse Wohnung.","gaps":[["hätte"]],"solution":"Sie **hätte** aber gern eine grosse Wohnung.","en":"Però le piacerebbe avere un appartamento grande.","why":"*eine Wohnung haben*: la forma del desiderio di *haben* è **hätte**. Non serve un infinito.","source":"k2"}]},{"no":"2","tag":"A1","instruction":"Was denken die Personen?","instruction_en":"Che cosa pensano le persone?","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Abbina ogni immagine a un'espressione del riquadro.","box":["wäre ich pünktlich im Büro","würde ich jetzt im Garten sitzen","müsste ich nicht bei Regen Velo fahren"],"box_exact":true,"items":[{"label":"1","lead":"Immer muss ich arbeiten!","text":"Wenn ich nicht arbeiten müsste, ___.","gaps":[["würde ich jetzt im Garten sitzen"]],"solution":"Wenn ich nicht arbeiten müsste, **würde ich jetzt im Garten sitzen**.","en":"Se non dovessi lavorare, adesso sarei seduto in giardino.","why":"L'immagine 1 lo mostra mentre lavora, poi mentre sogna su una sdraio. Dopo una frase con *wenn* la principale comincia con il verbo (*würde*).","source":"kond"},{"label":"2","lead":"Warum habe ich kein Auto?","text":"Wenn ich ein Auto hätte, ___.","gaps":[["müsste ich nicht bei Regen Velo fahren"]],"solution":"Wenn ich ein Auto hätte, **müsste ich nicht bei Regen Velo fahren**.","en":"Se avessi una macchina, non dovrei andare in bici sotto la pioggia.","why":"Va in bici sotto la pioggia; una macchina gli risparmierebbe questo. *müsste* è il Konjunktiv II di *müssen*. *Velo* è la parola svizzera per *Fahrrad*.","source":"kond"},{"label":"3","lead":"Der Bus hat schon wieder Verspätung!","text":"Wenn der Bus keine Verspätung hätte, ___.","gaps":[["wäre ich pünktlich im Büro"]],"solution":"Wenn der Bus keine Verspätung hätte, **wäre ich pünktlich im Büro**.","en":"Se il bus non fosse in ritardo, sarei puntuale in ufficio.","why":"Un bus in ritardo la fa arrivare tardi al lavoro. *wäre* è il Konjunktiv II di *sein*.","source":"kond"}]},{"no":"2","part":"b","part_instruction":"Schreiben Sie die Sätze aus a neu.","part_instruction_en":"Riscrivi le frasi di a: comincia con la principale, poi la frase con wenn.","example":[{"label":"1","text":"Ich würde **jetzt im Garten sitzen, wenn ich nicht arbeiten müsste.**"}],"items":[{"label":"2","text":"Ich müsste ___.","gaps":[["nicht bei Regen Velo fahren, wenn ich ein Auto hätte","bei Regen nicht Velo fahren, wenn ich ein Auto hätte"]],"solution":"Ich müsste **nicht bei Regen Velo fahren, wenn ich ein Auto hätte.**","en":"Non dovrei andare in bici sotto la pioggia, se avessi una macchina.","why":"Prima la principale, poi la frase con *wenn*. Nella frase con *wenn* il verbo (*hätte*) va alla fine.","source":"wenn"},{"label":"3","text":"Ich wäre ___.","gaps":[["pünktlich im Büro, wenn der Bus keine Verspätung hätte"]],"solution":"Ich wäre **pünktlich im Büro, wenn der Bus keine Verspätung hätte.**","en":"Sarei puntuale in ufficio, se il bus non fosse in ritardo.","why":"Stesso schema: principale, virgola, *wenn* … verbo alla fine (*hätte*).","source":"wenn"}]},{"no":"3","tag":"A1","instruction":"Ordnen Sie zu.","instruction_en":"Completa con le parole del riquadro. Ogni parola si usa una volta; quelle barrate sono usate nell'esempio.","box":["könnte","wäre","hätten","würde","könnte","würde","wäre","würde","würde","müsste"],"box_used":[0,3],"box_exact":true,"example":[{"label":"a","text":"Ich **könnte** viel leichter eine Arbeit finden, wenn ich in der Stadt leben **würde**."}],"items":[{"label":"b","text":"Ich ___ einige Dinge anders machen, wenn ich Chefin in unserer Firma ___.","gaps":[["würde","müsste"],["wäre"]],"solution":"Ich **würde** einige Dinge anders machen, wenn ich Chefin in unserer Firma **wäre**.","en":"Farei alcune cose in modo diverso, se fossi a capo della nostra ditta.","why":"*machen* alla fine → **würde** + infinito. *Chefin sein* → **wäre**, alla fine della frase con *wenn*.","source":"k2"},{"label":"c","text":"Wenn ich Marco ___, ___ ich unbedingt eine Ausbildung machen.","gaps":[["wäre"],["würde","müsste"]],"solution":"Wenn ich Marco **wäre**, **würde** ich unbedingt eine Ausbildung machen.","en":"Se fossi Marco, farei assolutamente una formazione professionale.","why":"*Marco sein* → **wäre** (come *Wenn ich du wäre …*). La principale ha l'infinito *machen* → **würde**.","source":"k2"},{"label":"d","text":"Wenn ich frei entscheiden ___, ___ ich in einer kleinen Firma arbeiten.","gaps":[["könnte"],["würde"]],"solution":"Wenn ich frei entscheiden **könnte**, **würde** ich in einer kleinen Firma arbeiten.","en":"Se potessi decidere liberamente, lavorerei in una piccola ditta.","why":"*frei entscheiden können* → **könnte** alla fine della frase con *wenn*. Principale con *arbeiten* → **würde**.","source":"k2"},{"label":"e","text":"Wenn wir Kinder ___, ___ ich nur halbtags arbeiten.","gaps":[["hätten"],["müsste","würde"]],"solution":"Wenn wir Kinder **hätten**, **müsste** ich nur halbtags arbeiten.","en":"Se avessimo dei figli, dovrei lavorare solo a metà tempo.","why":"*Kinder haben* con *wir* → **hätten**. Il riquadro lascia **müsste** per l'ultimo spazio.","source":"k2","check":"*müsste* e *würde* sono entrambi tedesco corretto in b, c ed e (*Wenn wir Kinder hätten, würde ich nur halbtags arbeiten* va altrettanto bene). Il riquadro dice solo che tre spazi prendono *würde* e uno prende *müsste*; questa soluzione è la ripartizione più probabile. Chiedi al tuo insegnante quale vuole il libro."}]}]},{"page":"AB 132","heading":"B  Ich muss mich beeilen wegen meiner Arbeit.","heading_en":"Devo sbrigarmi a causa del mio lavoro.","exercises":[{"no":"9","tag":"B1","instruction":"Schreiben Sie die Antworten neu mit *weil*.","instruction_en":"Riscrivi le risposte con weil.","example":[{"label":"a","lead":"◆ Warum freust du dich denn so? ○ Wegen meiner guten Note in der Prüfung.","text":"Weil ich eine gute Note in der Prüfung habe."}],"items":[{"label":"b","lead":"◆ Warum ärgerst du dich denn so? ○ Wegen meiner unpünktlichen Freundin.","text":"Weil meine ___.","gaps":[["Freundin unpünktlich ist","Freundin immer unpünktlich ist","Freundin so unpünktlich ist","Freundin zu spät kommt","Freundin immer zu spät kommt"]],"solution":"Weil meine **Freundin unpünktlich ist.**","en":"Perché la mia ragazza non è puntuale.","why":"*wegen* + sostantivo diventa *weil* + una frase con un verbo; il verbo (*ist*) va alla fine.","source":"weil"},{"label":"c","lead":"◆ Warum geht ihr am Samstag nicht wandern? ○ Wegen des schlechten Wetters.","text":"","accept":["Weil das Wetter schlecht ist.","Weil das Wetter so schlecht ist."],"solution":"**Weil das Wetter schlecht ist.**","en":"Perché il tempo è brutto.","why":"*des schlechten Wetters* → *das Wetter ist schlecht*; dopo *weil* il verbo va alla fine.","source":"weil"},{"label":"d","lead":"◆ Warum bist du denn so nervös? ○ Wegen eines wichtigen Termins.","text":"","accept":["Weil ich einen wichtigen Termin habe.","Weil ich einen wichtigen Termin hab."],"solution":"**Weil ich einen wichtigen Termin habe.**","en":"Perché ho un appuntamento importante.","why":"*eines wichtigen Termins* → *ich habe einen wichtigen Termin* (accusativo dopo *haben*); verbo alla fine.","source":"weil"}]},{"no":"10","tag":"B2","instruction":"Ergänzen Sie: *wegen – weshalb – weil – deswegen – denn*.","instruction_en":"Completa con: wegen – weshalb – weil – deswegen – denn. Una parola può essere usata più volte.","box":["wegen","weshalb","weil","deswegen","denn"],"example":[{"label":"a","text":"Ich beginne bald eine Lehre als Hotelfachfrau. **Deswegen** lerne ich in den Ferien Deutsch."}],"items":[{"label":"b","text":"Ich verstehe ihn ___ seiner Aussprache nur schlecht.","gaps":[["wegen"]],"solution":"Ich verstehe ihn **wegen** seiner Aussprache nur schlecht.","en":"A causa della sua pronuncia lo capisco solo male.","why":"Segue un sostantivo (*seiner Aussprache*, genitivo), non una frase → la preposizione **wegen**.","source":"wegen"},{"label":"c","text":"Irgendwann möchte ich gern nach Italien reisen, ___ ich möchte gern das Meer sehen.","gaps":[["denn"]],"solution":"Irgendwann möchte ich gern nach Italien reisen, **denn** ich möchte gern das Meer sehen.","en":"Un giorno vorrei viaggiare in Italia, perché vorrei vedere il mare.","why":"Dopo lo spazio il verbo resta in 2a posizione (*ich möchte*) → **denn**. Con *weil* andrebbe alla fine.","source":"denn"},{"label":"d","text":"Ich muss mein Hörverstehen verbessern, ___ schaue ich viele Filme an.","gaps":[["deswegen","deshalb"]],"solution":"Ich muss mein Hörverstehen verbessern, **deswegen** schaue ich viele Filme an.","en":"Devo migliorare la comprensione orale, per questo guardo molti film.","why":"La seconda parte è la conseguenza, e il verbo viene subito dopo lo spazio (*schaue ich*) → **deswegen**.","source":"deswegen"},{"label":"e","text":"Meine Kinder haben schnell Deutsch gelernt, ___ sie im Kindergarten immer mit Schweizer Kindern zusammen sind.","gaps":[["weil"]],"solution":"Meine Kinder haben schnell Deutsch gelernt, **weil** sie im Kindergarten immer mit Schweizer Kindern zusammen sind.","en":"I miei figli hanno imparato il tedesco in fretta, perché all'asilo stanno sempre con bambini svizzeri.","why":"Il verbo è alla fine (*zusammen sind*) → **weil**.","source":"weil"},{"label":"f","text":"___ schreibst du die Wörter auf Kärtchen?","gaps":[["Weshalb"]],"solution":"**Weshalb** schreibst du die Wörter auf Kärtchen?","en":"Perché scrivi le parole su dei bigliettini?","why":"Serve una parola interrogativa: **Weshalb** significa *warum* (perché)."},{"label":"g","text":"Meine Schwester spricht schon fast fliessend Deutsch, ___ kann sie mir beim Deutschlernen helfen.","gaps":[["deswegen","deshalb"]],"solution":"Meine Schwester spricht schon fast fliessend Deutsch, **deswegen** kann sie mir beim Deutschlernen helfen.","en":"Mia sorella parla già il tedesco quasi correntemente, per questo può aiutarmi a impararlo.","why":"Conseguenza, e il verbo viene subito dopo lo spazio (*kann sie*) → **deswegen**.","source":"deswegen"}]},{"no":"11","marker":"◇","tag":"B2","instruction":"Im Sprachkurs. Ergänzen Sie: *weil – wegen – deswegen*.","instruction_en":"Al corso di lingua. Completa con: weil – wegen – deswegen.","box":["weil","wegen","deswegen"],"example":[{"label":"a","text":"Ich möchte einen Sprachkurs machen, **deswegen** bin ich jetzt hier."}],"items":[{"label":"b","text":"Die letzte Übung konnte ich nicht machen, ___ ich sie nicht verstanden habe.","gaps":[["weil"]],"solution":"Die letzte Übung konnte ich nicht machen, **weil** ich sie nicht verstanden habe.","en":"Non sono riuscito a fare l'ultimo esercizio, perché non l'avevo capito.","why":"Il verbo è alla fine (*verstanden habe*) → **weil**.","source":"weil"},{"label":"c","text":"Bei der Anmeldung war niemand da. ___ bin ich wieder nach Hause gegangen.","gaps":[["Deswegen","Deshalb"]],"solution":"Bei der Anmeldung war niemand da. **Deswegen** bin ich wieder nach Hause gegangen.","en":"All'iscrizione non c'era nessuno. Per questo sono tornato a casa.","why":"Una nuova frase che dà la conseguenza, con il verbo subito dopo lo spazio (*bin ich*) → **Deswegen**.","source":"deswegen"},{"label":"d","text":"Ich musste ___ meiner guten Noten zum Kursbeginn keinen Test machen.","gaps":[["wegen"]],"solution":"Ich musste **wegen** meiner guten Noten zum Kursbeginn keinen Test machen.","en":"Grazie ai miei bei voti non ho dovuto fare un test all'inizio del corso.","why":"Segue un gruppo nominale (*meiner guten Noten*, genitivo plurale) → **wegen**.","source":"wegen"},{"label":"e","text":"Es gibt einen extra Sprachkurs, ___ sich sehr viele Teilnehmer angemeldet haben.","gaps":[["weil"]],"solution":"Es gibt einen extra Sprachkurs, **weil** sich sehr viele Teilnehmer angemeldet haben.","en":"C'è un corso di lingua in più, perché si sono iscritti moltissimi partecipanti.","why":"Il verbo è alla fine (*angemeldet haben*) → **weil**.","source":"weil"},{"label":"f","text":"Ich konnte gestern ___ meiner Zahnschmerzen leider nicht in den Kurs kommen.","gaps":[["wegen"]],"solution":"Ich konnte gestern **wegen** meiner Zahnschmerzen leider nicht in den Kurs kommen.","en":"Ieri purtroppo non sono potuto venire al corso a causa del mal di denti.","why":"Segue un gruppo nominale (*meiner Zahnschmerzen*, genitivo plurale) → **wegen**.","source":"wegen"}]},{"no":"12","marker":"◆","tag":"B2","instruction":"Wer findet die besten Ausreden? Wählen Sie eine Situation und schreiben Sie.","instruction_en":"Chi trova le scuse migliori? Scegli una situazione e scrivi. Le risposte modello sono solo una possibilità ciascuna.","phrases":["Ich habe/bin … Deswegen …","Leider habe/bin ich …, weil/denn …","Wegen …"],"example":[{"label":"a","text":"Leider konnte ich die Küche nicht aufräumen, …"}],"items":[{"label":"a","lead":"Ihre Frau hat Sie gebeten, die Küche aufzuräumen. Sie haben aber lieber einen Film angeschaut.","text":"","open":true,"solution":"Leider konnte ich die Küche nicht aufräumen, **weil** ich plötzlich starke Rückenschmerzen hatte. Ich musste mich hinlegen. **Deswegen** habe ich einen Film angeschaut.","en":"Purtroppo non ho potuto riordinare la cucina, perché all'improvviso ho avuto un forte mal di schiena. Ho dovuto sdraiarmi. Per questo ho guardato un film.","why":"Usa *weil* (verbo alla fine: *hatte*) e *Deswegen* (verbo subito dopo: *habe ich*).","source":"weil"},{"label":"b","lead":"Sie sind nicht an die Abschlussprüfung von Ihrem Sprachkurs gegangen.","text":"","open":true,"solution":"**Wegen** einer Grippe bin ich nicht an die Abschlussprüfung gegangen. Ich hatte hohes Fieber, **deswegen** bin ich im Bett geblieben.","en":"A causa dell'influenza non sono andato all'esame finale. Avevo la febbre alta, per questo sono rimasto a letto.","why":"Usa *wegen* + genitivo (*einer Grippe*) e *deswegen* + verbo (*bin ich*).","source":"wegen"},{"label":"c","lead":"Sie kommen zum Essen am 80. Geburtstag Ihrer Grossmutter zwei Stunden zu spät.","text":"","open":true,"solution":"Es tut mir so leid! Leider bin ich zu spät gekommen, **denn** auf der Autobahn war ein Unfall. **Wegen** des Staus habe ich zwei Stunden verloren.","en":"Mi dispiace tanto! Purtroppo sono arrivato tardi, perché in autostrada c'era stato un incidente. A causa della coda ho perso due ore.","why":"*denn* lascia il verbo in 2a posizione (*war*). *wegen des Staus*: genitivo di *der Stau*.","source":"denn"}]}]}],"sources":[{"id":"k2","title":"grammis: Konjunktiv II","url":"https://grammis.ids-mannheim.de/terminologie/401"},{"id":"kond","title":"grammis: Konditionalgefüge (frasi ipotetiche, comprese quelle irreali con il Konjunktiv II)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/997"},{"id":"wenn","title":"dizionario dei connettivi di grammis: wenn (subordinante, verbo alla fine)","url":"https://grammis.ids-mannheim.de/konnektoren/407100"},{"id":"weil","title":"dizionario dei connettivi di grammis: weil (subordinante, verbo alla fine)","url":"https://grammis.ids-mannheim.de/konnektoren/406991"},{"id":"denn","title":"dizionario dei connettivi di grammis: denn (causale, il verbo resta in 2a posizione)","url":"https://grammis.ids-mannheim.de/konnektoren/406860"},{"id":"deswegen","title":"dizionario dei connettivi di grammis: deswegen (conseguenza; sta prima del verbo o in mezzo alla frase)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"wegen","title":"grammis: Wegen dem Regen oder wegen des Regens? (wegen con il genitivo)","url":"https://grammis.ids-mannheim.de/fragen/67"}]},{"id":"02-mehrere-sprachen","no":2,"title":"In mehreren Sprachen zu Hause","title_en":"Crescere con più lingue · lettura, post nel forum, cruciverba, parole preferite","added":"2026-11-09","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 4","pages":[{"page":"AB 135","heading":"E  In mehreren Sprachen zu Hause","heading_en":"A casa in più lingue","exercises":[{"no":"17","tag":"E2","instruction":"Zwei oder drei Sprachen in einer Familie – kein Problem?","instruction_en":"Due o tre lingue in una famiglia – nessun problema?","part":"a","part_instruction":"Wer sagt was? Lesen Sie und ergänzen Sie die Namen.","part_instruction_en":"Chi dice cosa? Leggi i tre testi e scrivi il nome della persona che dice ciascuna frase.","reading":[{"label":"A · Amira, 33","text":"Ich denke, das ist manchmal schwierig, aber es geht. Bei uns ist das so: Ich bin Ägypterin und mein Deutsch ist noch nicht so gut, weil ich erst seit zwei Jahren in der Schweiz lebe. Mein Mann ist Schweizer. Wir haben uns in Ägypten kennengelernt, weil er dort sechs Jahre für eine Schweizer Firma gearbeitet hat. Jetzt leben wir seit fast zwei Jahren in Basel. Unsere Kinder sprechen sehr gut Arabisch und jetzt auch schon ziemlich gut Schweizerdeutsch. Mein Mann hat zwar in Ägypten mit ihnen Schweizerdeutsch gesprochen, aber er war ja nicht so viel zu Hause und in der Familie haben wir immer Arabisch gesprochen. Darum können das die Kinder viel besser. Manchmal verwenden sie auch zwei Sprachen in einem Satz. Wenn sie ein Wort nicht auf Schweizerdeutsch wissen, dann sagen sie einfach ein arabisches mitten im deutschen Satz. Aber ich finde das okay. Bald kommen sie in die Schule und dann werden sie sowieso besser Schweizerdeutsch als Arabisch sprechen."},{"label":"B · Janusz, 22","text":"Ich bin Pole, und als ich sechs Jahre alt war, sind wir in die Schweiz umgezogen. Meine Schwester und ich sind natürlich gleich in eine öffentliche Schule gegangen und konnten nach einem Jahr fliessend Hochdeutsch sprechen. Für meine Eltern war es schwieriger, denn meine Mutter war Hausfrau und hatte nicht so viel Kontakt zu Schweizern. Nach zwei Jahren wollten meine Schwester und ich nur noch Deutsch sprechen und wir haben unseren Eltern immer auf Deutsch geantwortet. Wir wollten nicht, dass unsere Eltern oder unsere Grossmutter mit uns Polnisch sprechen, wenn andere Kinder zu Besuch waren oder sie uns von der Schule abgeholt haben. Ich glaube, alle Kinder wollen sein wie die anderen Kinder und dazu gehört auch, dieselbe Sprache zu sprechen. Natürlich ist mein Polnisch nicht so gut wie mein Deutsch, aber ich verstehe alles und kann auch ziemlich gut Alltagsgespräche führen. Das ist genug für mich und ich freue mich, dass ich mich mit unseren polnischen Verwandten unterhalten kann. Ich finde, man sollte daraus nicht so ein Problem machen."},{"label":"C · Yara, 18","text":"Ich komme aus Syrien. Ich bin mit drei Sprachen aufgewachsen, denn mein Vater hat für eine internationale Firma gearbeitet und wir haben auch einige Jahre in der Türkei und in Russland gelebt. Aus diesem Grund spreche ich sehr gut Arabisch, Türkisch und Russisch. Allerdings kann ich Arabisch am besten, weil wir in der Familie immer Arabisch gesprochen haben, egal in welchem Land wir waren. Jetzt leben wir in in der Schweiz und ich lerne seit zwei Jahren Deutsch. Das kann ich noch nicht so gut. Ich persönlich finde es sehr gut, dass ich mit drei Sprachen aufgewachsen bin, denn ich habe viele Vorteile im Beruf. Ich möchte Übersetzerin werden und so muss ich die Sprachen nicht mehr lernen. Das ist doch super, oder?"}],"items":[{"label":"1","text":"«Kinder wollen dieselbe Sprache sprechen wie ihre Freunde.» Name: ___","gaps":[["Janusz"]],"solution":"«Kinder wollen dieselbe Sprache sprechen wie ihre Freunde.» Name: **Janusz**","en":"“I bambini vogliono parlare la stessa lingua dei loro amici.” – Janusz","why":"Janusz (testo B): *alle Kinder wollen sein wie die anderen Kinder und dazu gehört auch, dieselbe Sprache zu sprechen.*"},{"label":"2","text":"«Es ist doch gut, wenn man mehrere Sprachen sehr gut spricht.» Name: ___","gaps":[["Yara"]],"solution":"«Es ist doch gut, wenn man mehrere Sprachen sehr gut spricht.» Name: **Yara**","en":"“È bello parlare molto bene più lingue, no?” – Yara","why":"Yara (testo C): *Ich persönlich finde es sehr gut, dass ich mit drei Sprachen aufgewachsen bin, denn ich habe viele Vorteile im Beruf.*"},{"label":"3","text":"«Meine Kinder wechseln zwischen zwei Sprachen.» Name: ___","gaps":[["Amira"]],"solution":"«Meine Kinder wechseln zwischen zwei Sprachen.» Name: **Amira**","en":"“I miei figli passano da una lingua all'altra.” – Amira","why":"Amira (testo A): *Manchmal verwenden sie auch zwei Sprachen in einem Satz.* È l'unica che parla dei propri figli."}]},{"no":"17","part":"b","part_instruction":"Was ist richtig? Lesen Sie noch einmal und kreuzen Sie an.","part_instruction_en":"Che cosa è giusto? Rileggi i testi. Scrivi *richtig* (giusto) o *falsch* (sbagliato) dopo ogni frase; nel libro segni solo quelle giuste.","items":[{"label":"1","text":"Amiras Kinder sprechen besser Arabisch als Deutsch. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Amiras Kinder sprechen besser Arabisch als Deutsch. → **richtig**","en":"I figli di Amira parlano l'arabo meglio del tedesco. → giusto","why":"In famiglia si parla sempre arabo: *Darum können das die Kinder viel besser.* (Il loro tedesco qui è lo svizzero tedesco.)"},{"label":"2","text":"In Amiras Familie wird nur Deutsch gesprochen. → ___","gaps":[["falsch","f","nein"]],"solution":"In Amiras Familie wird nur Deutsch gesprochen. → **falsch**","en":"Nella famiglia di Amira si parla solo tedesco. → sbagliato","why":"Il contrario: *in der Familie haben wir immer Arabisch gesprochen.*"},{"label":"3","text":"Janusz hat sechs Jahre Deutsch gelernt. → ___","gaps":[["falsch","f","nein"]],"solution":"Janusz hat sechs Jahre Deutsch gelernt. → **falsch**","en":"Janusz ha imparato il tedesco per sei anni. → sbagliato","why":"Aveva sei anni quando la famiglia si è trasferita (*als ich sechs Jahre alt war*) e dopo un anno parlava correntemente l'alto tedesco."},{"label":"4","text":"Janusz und seine Schwester wollten mit ihren Eltern nicht Polnisch sprechen. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Janusz und seine Schwester wollten mit ihren Eltern nicht Polnisch sprechen. → **richtig**","en":"Janusz e sua sorella non volevano parlare polacco con i genitori. → giusto","why":"*Nach zwei Jahren wollten meine Schwester und ich nur noch Deutsch sprechen und wir haben unseren Eltern immer auf Deutsch geantwortet.*"},{"label":"5","text":"Yara spricht drei Sprachen fliessend. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Yara spricht drei Sprachen fliessend. → **richtig**","en":"Yara parla tre lingue correntemente. → giusto","why":"*Aus diesem Grund spreche ich sehr gut Arabisch, Türkisch und Russisch.* Il tedesco è la sua quarta lingua e non lo parla ancora bene."},{"label":"6","text":"Yara lernt jetzt bald auch Deutsch. → ___","gaps":[["falsch","f","nein"]],"solution":"Yara lernt jetzt bald auch Deutsch. → **falsch**","en":"Yara presto imparerà anche il tedesco. → sbagliato","why":"Non comincia presto (*bald*): impara già il tedesco da due anni (*ich lerne seit zwei Jahren Deutsch*)."}]}]},{"page":"AB 136","heading":"E  In mehreren Sprachen zu Hause","heading_en":"A casa in più lingue","exercises":[{"no":"18","tag":"E2 · Prüfung","instruction":"Einen Forumsbeitrag schreiben. Sie haben im Fernsehen eine Diskussionssendung zum Thema «Mehrsprachig aufwachsen» gesehen. Im Online-Forum der Sendung finden Sie folgende Meinung:","instruction_en":"Scrivere un post nel forum. Hai guardato un dibattito in TV sul crescere con più lingue. Nel forum online della trasmissione trovi questa opinione:","reading":[{"label":"Online-Forum · 15.01. 16.55 Uhr · Sandra (52 Jahre)","text":"Also, ich kann den Gästen in Ihrer Sendung überhaupt nicht zustimmen. Ich finde, dass Kinder zuerst einmal eine Sprache richtig lernen sollen. Denn sonst können sie am Ende gar keine Sprache gut. Sie sprechen dann zwar zwei oder drei Sprachen ein bisschen, mischen sie aber und sprechen keine Sprache fliessend und auch keine wirklich gut."}],"part":"a","part_instruction":"Machen Sie Notizen.","part_instruction_en":"Prendi appunti sulle quattro domande. Bastano appunti brevi, niente frasi complete. Gli appunti del modello sono una possibilità.","items":[{"label":"1","lead":"Kennen Sie eine Person, die mit zwei Sprachen aufwächst/aufgewachsen ist?","text":"","open":true,"solution":"Ja: der Sohn von meiner Nachbarin – Italienisch mit der Mutter, Schweizerdeutsch in der Schule","en":"Sì: il figlio della mia vicina – italiano con la madre, svizzero tedesco a scuola","why":"Solo appunti: un nome o una persona e quali lingue dove."},{"label":"2","lead":"Was finden Sie gut?","text":"","open":true,"solution":"zwei Sprachen ohne Kurs lernen, Kontakt mit der Familie im Ausland, Vorteile im Beruf","en":"imparare due lingue senza un corso, contatto con la famiglia all'estero, vantaggi nel lavoro","why":"Raccogli due o tre vantaggi; ti servono per *Ich finde es sehr gut, dass …* in b."},{"label":"3","lead":"Was könnte schwierig sein?","text":"","open":true,"solution":"die Sprachen mischen, eine Sprache ist schwächer, viel Arbeit für die Eltern","en":"mescolare le lingue, una lingua è più debole, molto lavoro per i genitori","why":"Questi vanno in *Es könnte schwierig sein, dass …* e *Auf der anderen Seite …* in b."},{"label":"4","lead":"Stimmen Sie Sandra zu?","text":"","open":true,"solution":"nein – Kinder lernen zwei Sprachen gut, wenn die Eltern viel mit ihnen sprechen","en":"no – i bambini imparano bene due lingue se i genitori parlano molto con loro","why":"Decidi sì o no e dai un motivo: diventa *Ich stimme Sandra (nicht) zu, denn …*."}]},{"no":"18","part":"b","part_instruction":"Schreiben Sie nun Ihre Meinung zum Thema (circa 80 Wörter).","part_instruction_en":"Ora scrivi la tua opinione sul tema (circa 80 parole). Usa i tuoi appunti di a e alcune delle espressioni.","phrases":["Ich denke, dass …","Ich finde es sehr gut/wichtig, dass …","Am allerwichtigsten ist … Deswegen/Daher/Aus diesem Grund …","Es könnte schwierig sein, dass …","Auf der anderen Seite …","Ich stimme Sandra (nicht) zu, denn …","**LERNTIPP** Sie brauchen diese Sätze, wenn Sie Ihre Meinung ausdrücken wollen. Wiederholen Sie sie möglichst oft."],"items":[{"label":"b","text":"","open":true,"solution":"Ich stimme Sandra nicht zu, **denn** viele Kinder lernen zwei Sprachen ohne Probleme. Der Sohn von meiner Nachbarin wächst mit Italienisch und Deutsch auf. Mit seiner Mutter spricht er Italienisch, in der Schule Schweizerdeutsch. Ich finde es sehr gut, dass er so früh zwei Sprachen lernt. Es könnte schwierig sein, dass er die Sprachen manchmal mischt. Auf der anderen Seite ist das bei kleinen Kindern normal. Am allerwichtigsten ist, dass die Eltern viel mit dem Kind sprechen. **Deswegen** sollte jeder Elternteil seine eigene Sprache sprechen.","en":"Non sono d'accordo con Sandra, perché molti bambini imparano due lingue senza problemi. Il figlio della mia vicina cresce con l'italiano e il tedesco. Con sua madre parla italiano, a scuola svizzero tedesco. Trovo molto bello che impari due lingue così presto. Potrebbe essere difficile che a volte mescoli le lingue. D'altra parte, per i bambini piccoli è normale. La cosa più importante di tutte è che i genitori parlino molto con il bambino. Per questo ogni genitore dovrebbe parlare la propria lingua.","why":"Circa 85 parole, con sei delle espressioni. *denn* lascia il verbo al secondo posto (*lernen*); dopo *Deswegen* viene subito il verbo (*sollte*).","source":"deswegen"}]},{"no":"19","tag":"E3","instruction":"Lösen Sie das Rätsel.","instruction_en":"Risolvi il cruciverba. Ogni frase indica la prima lettera della parola mancante. La griglia non è mostrata qui: scrivi la parola intera. Nella griglia del libro la Ä occupa una sola casella.","items":[{"label":"a","lead":"Unser Heimatland ist Spanien. Wir s… aus Spanien.","text":"___","gaps":[["stammen"]],"solution":"**stammen**","en":"Il nostro paese d'origine è la Spagna. Veniamo dalla Spagna.","why":"*aus einem Land stammen* = provenire da un paese (come *kommen aus*)."},{"label":"b","lead":"Jolanda und Mike sehen sich sechs Monate nicht. Das ist eine lange T… .","text":"___","gaps":[["Trennung"]],"solution":"**Trennung**","en":"Jolanda e Mike non si vedono per sei mesi. È una lunga separazione.","why":"*die Trennung* = separazione, il sostantivo di *sich trennen*. *eine lange* → un sostantivo femminile."},{"label":"c","lead":"Deutsch und Arabisch haben nicht die gleiche S… .","text":"___","gaps":[["Schrift"]],"solution":"**Schrift**","en":"Il tedesco e l'arabo non hanno la stessa scrittura.","why":"*die Schrift* = scrittura, le lettere con cui si scrive una lingua. L'arabo usa un altro alfabeto."},{"label":"d","lead":"Peter lebt jetzt in Amerika. Seit er dort lebt, hat er sich stark v… .","text":"___","gaps":[["verändert"]],"solution":"**verändert**","en":"Peter ora vive in America. Da quando vive lì, è cambiato molto.","why":"*sich verändern* = cambiare (come persona). Perfekt: *hat sich verändert*. La Ä occupa una sola casella."},{"label":"e","lead":"Sie schreibt Bücher. Sie ist A… von Beruf.","text":"___","gaps":[["Autorin"]],"solution":"**Autorin**","en":"Scrive libri. Di professione è un'autrice.","why":"*Sie* → la forma femminile con *-in*: *der Autor → die Autorin*. Nessun articolo dopo *sein … von Beruf*."},{"label":"f","lead":"Die Kinder machen ihre Hausaufgaben nicht. Deshalb s… die Eltern mit ihnen.","text":"___","gaps":[["schimpfen"]],"solution":"**schimpfen**","en":"I bambini non fanno i compiti. Per questo i genitori li sgridano.","why":"*mit jemandem schimpfen* = sgridare qualcuno. Soggetto plurale *die Eltern* → *schimpfen*. Dopo *Deshalb* viene subito il verbo."},{"label":"g","lead":"Sie arbeitet erst seit wenigen Monaten. Sie hat noch wenig E… in ihrem Beruf.","text":"___","gaps":[["Erfahrung"]],"solution":"**Erfahrung**","en":"Lavora solo da pochi mesi. Ha ancora poca esperienza nel suo lavoro.","why":"*die Erfahrung* = esperienza. *wenig Erfahrung haben* = avere poca esperienza."},{"label":"h","lead":"Jetzt haben wir ein Chaos. Alles ist d… .","text":"___","gaps":[["durcheinander"]],"solution":"**durcheinander**","en":"Ora abbiamo il caos. È tutto in disordine.","why":"*durcheinander sein* = essere in disordine, confuso. Si scrive in una parola."},{"label":"i","lead":"Für Ye-Jon tönen die Laute P und F gleich. Sie kann sie nicht u… .","text":"___","gaps":[["unterscheiden"]],"solution":"**unterscheiden**","en":"Per Ye-Jon i suoni P e F suonano uguali. Non riesce a distinguerli.","why":"*unterscheiden* = distinguere. Con *kann* l'infinito va in fondo. *tönen* è svizzero per *klingen* (suonare)."},{"label":"j","lead":"Ich reise in den Ferien nach Griechenland, aber leider kann ich kein G… .","text":"___","gaps":[["Griechisch"]],"solution":"**Griechisch**","en":"In vacanza vado in Grecia, ma purtroppo non so parlare il greco.","why":"*Griechisch* = la lingua greca, con la maiuscola. *kein Griechisch können* = non saper parlare il greco."},{"label":"k","lead":"Er isst nur Gemüse und Reis. Er isst a… Gemüse und Reis.","text":"___","gaps":[["ausschliesslich"]],"solution":"**ausschliesslich**","en":"Mangia solo verdura e riso. Mangia esclusivamente verdura e riso.","why":"*ausschliesslich* = esclusivamente, nient'altro che. Grafia svizzera con *ss*; in Germania si scrive con la s scharf (Eszett)."},{"label":"★","lead":"Lösungswort (die markierte Zeile im Rätsel)","text":"___","gaps":[["Muttersprache"]],"solution":"**Muttersprache**","en":"Parola risolutiva (la riga evidenziata nella griglia): lingua madre","why":"Ogni parola dà una lettera della riga evidenziata: stam**M**en, trenn**U**ng, schrif**T**, (T nella griglia), veränd**E**rt, auto**R**in, (S nella griglia), schim**P**fen, erfah**R**ung, durchein**A**nder, unters**C**heiden, griec**H**isch, ausschli**E**sslich."}]}]},{"page":"AB 137","heading":"E  In mehreren Sprachen zu Hause","heading_en":"A casa in più lingue","exercises":[{"no":"20","tag":"E3","instruction":"Mein schönstes deutsches Wort","instruction_en":"La mia parola tedesca più bella","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Abbina ogni foto a una parola del riquadro. I pallini colorati del libro indicano l'articolo: blu = der, verde = das, rosso = die.","box":["Sommervogel","Caramelchöpfli","Sternschnuppe"],"box_exact":true,"items":[{"label":"1","lead":"(Foto 1: ein Dessert mit Karamellsauce auf einem Teller)","text":"___","gaps":[["Caramelchöpfli","das Caramelchöpfli"]],"solution":"**Caramelchöpfli**","en":"das Caramelchöpfli – crème caramel (un dolce al cucchiaio al caramello)","why":"Nome svizzero della crème caramel. *Chöpfli* in svizzero tedesco significa “testolina” (*Kopf*). Pallino verde → *das*.","source":"hueber-tr"},{"label":"2","lead":"(Foto 2: ein Stern mit einem langen, hellen Schweif am Nachthimmel)","text":"___","gaps":[["Sternschnuppe","die Sternschnuppe"]],"solution":"**Sternschnuppe**","en":"die Sternschnuppe – stella cadente","why":"*der Stern* = stella; *die Sternschnuppe* = stella cadente. Pallino rosso → *die*."},{"label":"3","lead":"(Foto 3: ein blauer Schmetterling auf einer orangen Blume)","text":"___","gaps":[["Sommervogel","der Sommervogel"]],"solution":"**Sommervogel**","en":"der Sommervogel – farfalla","why":"Parola svizzera per *der Schmetterling* (farfalla); il Duden la segna come *schweizerisch, sonst landschaftlich*. Pallino blu → *der*.","source":"sommervogel"}]},{"no":"20","part":"b","part_instruction":"Warum findet wohl jemand genau diese Wörter am schönsten? Was meinen Sie? Machen Sie Notizen und sprechen Sie.","part_instruction_en":"Perché qualcuno potrebbe trovare proprio queste parole le più belle? Tu che cosa ne pensi? Prendi appunti, poi parlatene. Gli appunti del modello sono una possibilità.","example":[{"text":"Sommervogel: so farbig, …"}],"items":[{"label":"1","lead":"Sommervogel","text":"","open":true,"solution":"so farbig und leicht, erinnert an den Sommer, lustig: das Tier ist ja kein Vogel","en":"così colorata e leggera, ricorda l'estate, buffo: l'animale non è affatto un uccello","why":"Pensa a che cosa ti fa vedere o sentire la parola e a come suona."},{"label":"2","lead":"Caramelchöpfli","text":"","open":true,"solution":"süss, erinnert an die Kindheit, tönt lustig und typisch schweizerisch","en":"dolce, ricorda l'infanzia, suona buffa e tipicamente svizzera","why":"*tönen* = svizzero per *klingen* (suonare)."},{"label":"3","lead":"Sternschnuppe","text":"","open":true,"solution":"romantisch, man kann sich etwas wünschen, tönt weich","en":"romantica, si può esprimere un desiderio, suona morbida","why":"Bastano appunti brevi: aggettivi e un motivo."}]},{"no":"20","part":"c","part_instruction":"Hören Sie und vergleichen Sie. (Tracks 23–25)","part_instruction_en":"Ascolta e confronta con i tuoi appunti di b. L'audio non è su questo sito; il riassunto è tratto dalla trascrizione ufficiale di Hueber.","items":[{"label":"1–3","text":"","open":true,"solution":"1 Die Frau: «Sommervogel» – sie denkt an den Sommer; lustig, denn das Tier ist kein Vogel, sondern ein Insekt. 2 Der Mann: «Caramelchöpfli» – er isst es gern und denkt an seine Kindheit und seine Grossmutter. 3 Der junge Mann: «Sternschnuppe» – man kann sich etwas wünschen, wenn man eine sieht.","en":"1 La donna: “Sommervogel” – pensa all'estate; buffo, perché l'animale è un insetto, non un uccello. 2 L'uomo: “Caramelchöpfli” – lo mangia volentieri e pensa alla sua infanzia e a sua nonna. 3 Il ragazzo: “Sternschnuppe” – si può esprimere un desiderio quando se ne vede una.","why":"Confronta: quali dei tuoi motivi di b hanno dato anche i parlanti?","source":"hueber-tr"}]},{"no":"20","part":"d","part_instruction":"Hören Sie noch einmal und ergänzen Sie.","part_instruction_en":"Ascolta di nuovo e completa gli spazi vuoti.","items":[{"label":"1","text":"Die Frau ist Deutschlernerin. Sie findet das Wort ___ lustig, weil das Tier gar kein Vogel ist. Sie sagt, dass das Wort in ihrer Muttersprache sogar ___ tönt.","gaps":[["Sommervogel","«Sommervogel»"],["noch schöner","schöner"]],"solution":"Die Frau ist Deutschlernerin. Sie findet das Wort **Sommervogel** lustig, weil das Tier gar kein Vogel ist. Sie sagt, dass das Wort in ihrer Muttersprache sogar **noch schöner** tönt.","en":"La donna sta imparando il tedesco. Trova buffa la parola “Sommervogel” perché l'animale non è affatto un uccello. Dice che nella sua lingua madre la parola suona ancora più bella.","why":"Trascrizione: *In meiner Muttersprache Italienisch ist das Wort sogar noch schöner: Farfalla!*","source":"hueber-tr"},{"label":"2","text":"Dem Mann gefällt das Wort ___ am besten, weil er diese gern isst. Dann erinnert er sich gern an seine ___, weil sie immer dieses süsse ___ gemacht hat.","gaps":[["Caramelchöpfli","«Caramelchöpfli»"],["Grossmutter","Grosi","Oma"],["Dessert","Caramelchöpfli"]],"solution":"Dem Mann gefällt das Wort **Caramelchöpfli** am besten, weil er diese gern isst. Dann erinnert er sich gern an seine **Grossmutter**, weil sie immer dieses süsse **Dessert** gemacht hat.","en":"All'uomo piace soprattutto la parola “Caramelchöpfli” perché ama mangiarli. Allora ricorda volentieri sua nonna, perché faceva sempre questo dolce.","why":"Trascrizione: *weil meine Grossmutter so gute Caramelchöpfli gemacht hat … ein süsses Dessert*. Dice anche *Kindheit*, ma *sie … gemacht hat* richiede una persona.","source":"hueber-tr"},{"label":"3","text":"Der Mann findet, dass ___ das schönste deutsche Wort ist. Wenn man am Himmel ___, dann kann man sich etwas wünschen.","gaps":[["Sternschnuppe","«Sternschnuppe»"],["eine Sternschnuppe sieht","Sternschnuppen sieht"]],"solution":"Der Mann findet, dass **Sternschnuppe** das schönste deutsche Wort ist. Wenn man am Himmel **eine Sternschnuppe sieht**, dann kann man sich etwas wünschen.","en":"L'uomo pensa che “Sternschnuppe” sia la parola tedesca più bella. Quando si vede una stella cadente nel cielo, si può esprimere un desiderio.","why":"Trascrizione: *Weil man sich immer etwas wünschen kann, wenn man am Himmel eine Sternschnuppe sieht.* Nella frase con *wenn* il verbo (*sieht*) va in fondo.","source":"hueber-tr"}]},{"no":"21","tag":"E3","instruction":"Mein Lieblingswort","instruction_en":"La mia parola preferita","part":"a","part_instruction":"Welches deutsche Wort und welches Wort in Ihrer Muttersprache gefallen Ihnen? Warum? Schreiben Sie.","part_instruction_en":"Quale parola tedesca e quale parola della tua lingua madre ti piacciono? Perché? Scrivi un breve testo usando le espressioni. La risposta modello è una possibilità.","phrases":["Wenn ich … höre, dann denke ich an …","Deshalb finde ich …","Dieses Wort ist …","Das tönt …","Für mich ist …","Auf Deutsch/In meiner Muttersprache …"],"example":[{"text":"Wenn ich das Wort «Sommervogel» höre, dann denke ich an …"}],"items":[{"label":"a","text":"","open":true,"solution":"Mein deutsches Lieblingswort ist «gemütlich». **Wenn** ich dieses Wort höre, **dann** denke ich an einen Winterabend mit Tee, Kerzen und Freunden. **Deshalb** finde ich es so schön. Das tönt weich und warm. In meiner Muttersprache Englisch gibt es kein Wort mit genau dieser Bedeutung. Auf Englisch gefällt mir das Wort «sunshine». Für mich ist es ein fröhliches Wort, denn es tönt hell und freundlich.","en":"La mia parola tedesca preferita è “gemütlich” (accogliente). Quando sento questa parola, penso a una sera d'inverno con tè, candele e amici. Per questo la trovo così bella. Suona morbida e calda. Nella mia lingua madre, l'Inglese, non c'è una parola con esattamente questo significato. In inglese mi piace la parola “sunshine”. Per me è una parola allegra, perché suona luminosa e amichevole.","why":"*Wenn …, dann* + verbo subito dopo (*denke ich*); *Deshalb* + verbo subito dopo (*finde ich*). Sostituisci con la tua lingua madre e le tue parole.","source":"wenn"}]},{"no":"21","part":"b","part_instruction":"Präsentieren Sie Ihren Text im Kurs.","part_instruction_en":"Presenta il tuo testo in classe. Nel modello trovi un possibile inizio.","items":[{"label":"b","text":"","open":true,"solution":"Ich möchte euch heute mein Lieblingswort vorstellen. Es ist das Wort «gemütlich». …","en":"Oggi vorrei presentarvi la mia parola preferita. È la parola “gemütlich”. …","why":"Comincia nominando la parola, poi leggi il tuo testo di a. *euch* per i compagni di classe, *Ihnen* se parli in modo formale."}]}]}],"sources":[{"id":"hueber-tr","title":"Hueber: Schritte plus Neu 5 Schweiz – Transkriptionen zum Arbeitsbuch (Lektion 4, Übung 20 c und d)","url":"https://www.hueber.de/media/36/Schritte-plus-Neu-5_CH_Transkriptionen_AB.pdf"},{"id":"sommervogel","title":"Duden: Sommervogel (schweizerisch, sonst landschaftlich = Schmetterling)","url":"https://www.duden.de/rechtschreibung/Sommervogel"},{"id":"deswegen","title":"grammis, dizionario dei connettori: deswegen (conseguenza; sta prima del verbo o in mezzo)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"wenn","title":"grammis, dizionario dei connettori: wenn (subordinante, verbo in fondo)","url":"https://grammis.ids-mannheim.de/konnektoren/407100"}]}];
